DROP TABLE chip_ledger;
CREATE TABLE "public"."chip_ledger"("id" uuid NOT NULL,
"performed_by" uuid NOT NULL,
"from_type" text NOT NULL,
"from_entity_id" uuid,
"from_label" text,
"to_type" text NOT NULL,
"to_entity_id" uuid,
"to_label" text,
"amount" numeric(15,2) NOT NULL,
"category" text NOT NULL,
"description" text,
"notes" text,
"club_id" uuid,
"union_id" uuid,
"table_id" uuid,
"hand_id" uuid,
"tournament_id" uuid,
"created_at" timestamp with time zone NOT NULL,
"idempotency_key" text,
"correlation_id" uuid,
"causation_id" uuid,
"settlement_id" text,
"epoch_id" integer,
"actor_service" text,
"db_role" text,
"pre_from_balance" numeric,
"post_from_balance" numeric,
"pre_to_balance" numeric,
"post_to_balance" numeric,
"status" text NOT NULL,
"metadata" jsonb,
"chain_seq" bigint,
"prev_hash" text,
"row_hash" text);
CREATE TABLE "public"."ca_settlements"("id" uuid NOT NULL,
"settlement_type" text NOT NULL,
"external_ref" text NOT NULL,
"state" text NOT NULL,
"club_id" uuid,
"union_id" uuid,
"table_id" uuid,
"tournament_id" uuid,
"hand_id" uuid,
"idempotency_key" text,
"correlation_id" uuid,
"epoch_id" integer,
"totals" jsonb NOT NULL,
"error_detail" text,
"created_at" timestamp with time zone NOT NULL,
"updated_at" timestamp with time zone NOT NULL);
CREATE TABLE "public"."settlement_idempotency_keys"("table_id" uuid NOT NULL,
"hand_id" uuid NOT NULL,
"status" text NOT NULL,
"result" jsonb,
"error" text,
"attempt_count" integer NOT NULL,
"first_attempt_at" timestamp with time zone NOT NULL,
"last_attempt_at" timestamp with time zone NOT NULL,
"completed_at" timestamp with time zone);
CREATE TABLE "public"."hand_atomic_commits"("table_id" uuid NOT NULL,
"hand_number" bigint NOT NULL,
"hand_id" uuid NOT NULL,
"payload_hash" text NOT NULL,
"stack_result" jsonb NOT NULL,
"committed_at" timestamp with time zone NOT NULL,
"post_commit_payload" jsonb,
"post_commit_request_hash" text,
"post_commit_payload_hash" text,
"post_commit_completed_at" timestamp with time zone,
"post_commit_result" jsonb);
CREATE TABLE "public"."wallet_credit_idempotency"("key" text NOT NULL,
"user_id" uuid,
"amount" numeric,
"created_at" timestamp with time zone NOT NULL);
ALTER TABLE chip_ledger ADD PRIMARY KEY(id);
ALTER TABLE ca_settlements ADD PRIMARY KEY(id);
ALTER TABLE settlement_idempotency_keys ADD PRIMARY KEY(table_id,hand_id);
ALTER TABLE hand_atomic_commits ADD PRIMARY KEY(table_id,hand_number);
ALTER TABLE wallet_credit_idempotency ADD PRIMARY KEY(key);
CREATE TABLE union_pnl_cash_outcome_resolutions(table_id uuid,hand_number bigint,hand_id uuid,outcome_payload_hash text,outcome_evidence_md5 text,proof jsonb,reason text,resolved_at timestamptz,resolved_by text,resolution_kind text,PRIMARY KEY(table_id,hand_number));
